-- =====================================================================
-- setup_all.sql — ONE-PASTE SETUP for the Supabase SQL Editor.
-- It is simply the 4 migrations + seed.sql + the admin promotion, in order.
-- (Generated by: bash scripts/build-setup-all.sh — edit the source files, not this one.)
--
-- Before running: create the user studio@artstudio.in in
-- Authentication -> Users -> Add user (tick "Auto Confirm User").
-- Safe to run more than once.
-- =====================================================================

-- ##################### supabase/migrations/001_schema.sql #####################
-- =====================================================================
-- 001_schema.sql — tables, relationships, constraints and indexes
-- Run this first in the Supabase SQL Editor.
--
-- Golden rule of this project: the browser is never trusted.
-- Every rule that matters (prices, dates, sizes, statuses, ownership)
-- is enforced here in the database, not only in app.js.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Studio settings (one row). Holds seeded values such as the mural rate,
-- so the price is always calculated from the database, never the client.
-- ---------------------------------------------------------------------
create table if not exists public.studio_settings (
  id                  boolean primary key default true,
  currency            text    not null default 'INR',
  mural_rate_per_sqft numeric(10,2) not null,
  constraint studio_settings_single_row check (id),          -- only one row can exist
  constraint studio_settings_rate_positive check (mural_rate_per_sqft > 0),
  constraint studio_settings_currency_format check (currency ~ '^[A-Z]{3}$')
);

-- ---------------------------------------------------------------------
-- Profiles: one row per Supabase Auth user. Stores the ROLE.
-- The role is never read from the browser; a trigger (002) always
-- creates new users as 'customer'. Only the database owner can promote
-- someone to 'studio' (the studio admin role from seed.json).
-- ---------------------------------------------------------------------
create table if not exists public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text not null,
  full_name   text not null default '',
  role        text not null default 'customer',
  created_at  timestamptz not null default now(),
  constraint profiles_role_valid check (role in ('customer', 'studio'))
);

-- ---------------------------------------------------------------------
-- Paintings. IDs come from seed.json (e.g. 'p-001'); new paintings added
-- by the studio get a generated 'p-xxxxxxxx' id.
-- status = 'available' or 'sold'. A painting becomes 'sold' when bought
-- and goes back to 'available' only when THAT order is cancelled.
-- ---------------------------------------------------------------------
create table if not exists public.paintings (
  id          text primary key default ('p-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
  title       text not null,
  artist      text not null,
  description text not null default '',
  price       numeric(12,2) not null,
  image_url   text not null default '',
  status      text not null default 'available',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint paintings_title_not_blank  check (length(btrim(title)) > 0),
  constraint paintings_artist_not_blank check (length(btrim(artist)) > 0),
  constraint paintings_price_range      check (price > 0 and price <= 10000000),
  constraint paintings_status_valid     check (status in ('available', 'sold'))
);

create index if not exists paintings_status_idx on public.paintings (status);

-- ---------------------------------------------------------------------
-- Orders (painting purchases). Status: 'placed' or 'cancelled'.
-- price is COPIED from the painting inside the purchase function, so a
-- customer can never send their own price.
-- ---------------------------------------------------------------------
create table if not exists public.orders (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.profiles (id) on delete cascade,
  painting_id   text not null references public.paintings (id) on delete restrict,
  price         numeric(12,2) not null,
  status        text not null default 'placed',
  created_at    timestamptz not null default now(),
  cancelled_at  timestamptz,
  constraint orders_status_valid check (status in ('placed', 'cancelled')),
  constraint orders_price_positive check (price > 0),
  -- a cancelled order must have a cancel time, a placed one must not
  constraint orders_cancelled_at_matches check ((status = 'cancelled') = (cancelled_at is not null))
);

-- THE key rule: at most ONE active ('placed') order per painting.
-- Even if two customers click "Buy" at the same millisecond, the second
-- insert fails with a unique violation. Cancelled orders don't count.
create unique index if not exists orders_one_active_per_painting
  on public.orders (painting_id) where status = 'placed';

create index if not exists orders_customer_idx on public.orders (customer_id, created_at desc);

-- ---------------------------------------------------------------------
-- Wall (mural) bookings.
-- Status: requested -> confirmed | declined ; requested/confirmed -> cancelled
-- ---------------------------------------------------------------------
create table if not exists public.wall_bookings (
  id              uuid primary key default gen_random_uuid(),
  customer_id     uuid not null references public.profiles (id) on delete cascade,
  booking_date    date not null,
  wall_size_sqft  numeric(6,2) not null,
  address         text not null,
  rate_per_sqft   numeric(10,2) not null,   -- copied from studio_settings at booking time
  total_price     numeric(12,2) not null,   -- rate * size, calculated by the database
  status          text not null default 'requested',
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint bookings_size_range      check (wall_size_sqft between 10 and 500),
  constraint bookings_address_present check (length(btrim(address)) between 5 and 500),
  constraint bookings_rate_positive   check (rate_per_sqft > 0),
  constraint bookings_price_correct   check (total_price = round(rate_per_sqft * wall_size_sqft, 2)),
  constraint bookings_status_valid    check (status in ('requested', 'confirmed', 'declined', 'cancelled'))
);

-- One ACTIVE booking per date. Declined/cancelled bookings are excluded,
-- so they free the date for someone else.
create unique index if not exists bookings_one_active_per_date
  on public.wall_bookings (booking_date) where status in ('requested', 'confirmed');

create index if not exists bookings_customer_idx on public.wall_bookings (customer_id, booking_date desc);

-- ---------------------------------------------------------------------
-- Pottery reference data (from seed.json) and custom requests.
-- ---------------------------------------------------------------------
create table if not exists public.pottery_items (
  id    text primary key,
  name  text not null unique
);

create table if not exists public.glazes (
  id    text primary key,
  name  text not null unique
);

create table if not exists public.pottery_requests (
  id           uuid primary key default gen_random_uuid(),
  customer_id  uuid not null references public.profiles (id) on delete cascade,
  item_id      text not null references public.pottery_items (id),
  glaze_id     text not null references public.glazes (id),
  quantity     integer not null,
  needed_by    date not null,
  notes        text not null default '',
  status       text not null default 'requested',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  constraint pottery_quantity_range check (quantity between 1 and 12),
  constraint pottery_notes_length   check (length(notes) <= 500),
  constraint pottery_status_valid   check (status in ('requested', 'accepted', 'declined', 'cancelled'))
);

create index if not exists pottery_customer_idx on public.pottery_requests (customer_id, created_at desc);
create index if not exists pottery_status_idx   on public.pottery_requests (status);

-- ##################### supabase/migrations/002_auth_and_roles.sql #####################
-- =====================================================================
-- 002_auth_and_roles.sql — profiles, roles and permission helpers
--
-- HTTP status codes: Supabase's REST layer (PostgREST) turns an error
-- raised with SQLSTATE 'PTxyz' into HTTP status xyz. So:
--   PT401 = not logged in, PT403 = wrong role, PT404 = not found / not yours,
--   PT409 = conflict (already sold, date taken), PT400 = validation error.
-- =====================================================================

-- ---------------------------------------------------------------------
-- When someone signs up through Supabase Auth, create their profile.
-- SECURITY: the role is ALWAYS 'customer'. We deliberately ignore any
-- "role" a user might put in their sign-up metadata.
-- ---------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (
    new.id,
    coalesce(new.email, ''),
    left(btrim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), 100),
    'customer'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Backfill profiles for users that existed before this migration ran.
insert into public.profiles (id, email, role)
select u.id, coalesce(u.email, ''), 'customer'
from auth.users u
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- Defence in depth: even if someone later grants UPDATE on profiles by
-- mistake, a logged-in user (JWT role 'authenticated' or 'anon') can
-- never change a role. Only the SQL Editor (postgres) or the
-- service_role key used by scripts/provision-studio.js can.
-- ---------------------------------------------------------------------
create or replace function public.protect_profile_role()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.role is distinct from old.role
     and coalesce(auth.role(), '') in ('anon', 'authenticated') then
    raise exception using errcode = 'PT403', message = 'You cannot change your own role.';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_protect_role on public.profiles;
create trigger profiles_protect_role
  before update on public.profiles
  for each row execute function public.protect_profile_role();

-- ---------------------------------------------------------------------
-- Permission helpers used by every business function in 003.
-- ---------------------------------------------------------------------

-- The role of the currently logged-in user, or NULL if not logged in.
create or replace function public.current_user_role()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select p.role from public.profiles p where p.id = auth.uid();
$$;

-- Used inside RLS policies. SECURITY DEFINER so it can read profiles
-- without triggering the profiles RLS policy (avoids infinite recursion).
create or replace function public.is_studio()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.current_user_role() = 'studio', false);
$$;

-- Raise 401 if not logged in. Returns the user's id.
create or replace function public.require_login()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or public.current_user_role() is null then
    raise exception using errcode = 'PT401', message = 'Please log in to do that.';
  end if;
  return auth.uid();
end;
$$;

-- Raise 401 if not logged in, 403 if logged in but not a customer.
create or replace function public.require_customer()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  user_id uuid := public.require_login();
begin
  if public.current_user_role() <> 'customer' then
    raise exception using errcode = 'PT403', message = 'Only customer accounts can do that.';
  end if;
  return user_id;
end;
$$;

-- Raise 401 if not logged in, 403 if logged in but not the studio admin.
create or replace function public.require_studio()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  user_id uuid := public.require_login();
begin
  if public.current_user_role() <> 'studio' then
    raise exception using errcode = 'PT403', message = 'Only the studio admin can do that.';
  end if;
  return user_id;
end;
$$;

-- "Today" for the studio, in Indian Standard Time, so the 7/14/90-day and
-- 3-day rules don't shift depending on the server's time zone.
create or replace function public.studio_today()
returns date
language sql
stable
set search_path = ''
as $$
  select (now() at time zone 'Asia/Kolkata')::date;
$$;

-- ##################### supabase/migrations/003_business_functions.sql #####################
-- =====================================================================
-- 003_business_functions.sql — every write the website can make
--
-- The browser NEVER inserts/updates tables directly (see 004: no
-- INSERT/UPDATE/DELETE grants). It can only call these functions via
-- supabase.rpc('function_name', {...}).
--
-- Each function:
--   1. checks who is calling (401 / 403),
--   2. checks ownership (404 if the record isn't yours),
--   3. validates input and the status transition (400 / 409),
--   4. does the work in ONE transaction (a function call is atomic:
--      if anything raises an error, every change in it is rolled back).
--
-- SECURITY DEFINER = the function runs with the owner's rights, which is
-- why it must do its own permission checks first. "set search_path = ''"
-- stops anyone from hijacking table names, so every name is qualified.
-- =====================================================================


-- =====================================================================
-- PAINTINGS & ORDERS
-- =====================================================================

-- Customer buys a painting. The price comes from the paintings table,
-- never from the browser.
create or replace function public.purchase_painting(p_painting_id text)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  painting    public.paintings;
  new_order   public.orders;
begin
  -- ATOMIC CLAIM: flip available -> sold in a single UPDATE.
  -- If two customers buy at the same time, Postgres locks the row; the
  -- second UPDATE waits, re-checks "status = 'available'", finds 'sold'
  -- and updates nothing. So only one buyer can ever win.
  update public.paintings
     set status = 'sold', updated_at = now()
   where id = p_painting_id
     and status = 'available'
  returning * into painting;

  if not found then
    if exists (select 1 from public.paintings where id = p_painting_id) then
      raise exception using errcode = 'PT409',
        message = 'Sorry, this painting has already been sold.';
    end if;
    raise exception using errcode = 'PT404', message = 'Painting not found.';
  end if;

  -- Second safety net: the unique index orders_one_active_per_painting.
  begin
    insert into public.orders (customer_id, painting_id, price)
    values (caller_id, painting.id, painting.price)
    returning * into new_order;
  exception when unique_violation then
    raise exception using errcode = 'PT409',
      message = 'Sorry, this painting has already been sold.';
  end;

  return new_order;
end;
$$;

-- Customer cancels their own order; the painting becomes available again.
create or replace function public.cancel_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  the_order   public.orders;
begin
  -- "FOR UPDATE" locks the order so a double-click can't cancel twice.
  -- Someone else's order looks exactly like a missing one: 404.
  select * into the_order
    from public.orders o
   where o.id = p_order_id and o.customer_id = caller_id
   for update;

  if not found then
    raise exception using errcode = 'PT404', message = 'Order not found.';
  end if;

  if the_order.status <> 'placed' then
    raise exception using errcode = 'PT409', message = 'This order is already cancelled.';
  end if;

  update public.orders
     set status = 'cancelled', cancelled_at = now()
   where id = the_order.id
  returning * into the_order;

  -- Restore availability. Only paintings that had a real order can reach
  -- this line, so paintings seeded as 'sold' (no order) stay sold forever.
  update public.paintings
     set status = 'available', updated_at = now()
   where id = the_order.painting_id
     and status = 'sold';

  return the_order;
end;
$$;

-- Shared validation for studio add/edit painting.
create or replace function public.validate_painting_input(
  p_title text, p_artist text, p_description text, p_price numeric, p_image_url text)
returns void
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_title is null or length(btrim(p_title)) = 0 or length(p_title) > 200 then
    raise exception using errcode = 'PT400', message = 'Title is required (max 200 characters).';
  end if;
  if p_artist is null or length(btrim(p_artist)) = 0 or length(p_artist) > 120 then
    raise exception using errcode = 'PT400', message = 'Artist is required (max 120 characters).';
  end if;
  if length(coalesce(p_description, '')) > 2000 then
    raise exception using errcode = 'PT400', message = 'Description must be at most 2000 characters.';
  end if;
  if p_price is null or p_price <= 0 or p_price > 10000000 then
    raise exception using errcode = 'PT400', message = 'Price must be between 1 and 1,00,00,000.';
  end if;
  if length(coalesce(p_image_url, '')) > 500 then
    raise exception using errcode = 'PT400', message = 'Image path is too long.';
  end if;
end;
$$;

-- Studio admin adds a new painting (always starts 'available').
create or replace function public.studio_add_painting(
  p_title text, p_artist text, p_description text, p_price numeric, p_image_url text)
returns public.paintings
language plpgsql
security definer
set search_path = ''
as $$
declare
  new_painting public.paintings;
begin
  perform public.require_studio();
  perform public.validate_painting_input(p_title, p_artist, p_description, p_price, p_image_url);

  insert into public.paintings (title, artist, description, price, image_url, status)
  values (btrim(p_title), btrim(p_artist), btrim(coalesce(p_description, '')),
          round(p_price, 2), btrim(coalesce(p_image_url, '')), 'available')
  returning * into new_painting;

  return new_painting;
end;
$$;

-- Studio admin edits a painting — only while it is still available.
create or replace function public.studio_update_painting(
  p_painting_id text, p_title text, p_artist text, p_description text,
  p_price numeric, p_image_url text)
returns public.paintings
language plpgsql
security definer
set search_path = ''
as $$
declare
  painting public.paintings;
begin
  perform public.require_studio();

  -- Lock the row so a purchase can't happen halfway through the edit.
  select * into painting from public.paintings where id = p_painting_id for update;
  if not found then
    raise exception using errcode = 'PT404', message = 'Painting not found.';
  end if;
  if painting.status <> 'available' then
    raise exception using errcode = 'PT409', message = 'Sold paintings cannot be edited.';
  end if;

  perform public.validate_painting_input(p_title, p_artist, p_description, p_price, p_image_url);

  update public.paintings
     set title = btrim(p_title),
         artist = btrim(p_artist),
         description = btrim(coalesce(p_description, '')),
         price = round(p_price, 2),
         image_url = btrim(coalesce(p_image_url, '')),
         updated_at = now()
   where id = p_painting_id
  returning * into painting;

  return painting;
end;
$$;


-- =====================================================================
-- WALL BOOKINGS
-- =====================================================================

-- Customer requests a mural on a date 7–90 days away.
create or replace function public.create_wall_booking(
  p_booking_date date, p_wall_size_sqft numeric, p_address text)
returns public.wall_bookings
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id     uuid := public.require_customer();
  days_ahead    integer;
  wall_size     numeric(6,2);
  rate          numeric(10,2);
  new_booking   public.wall_bookings;
begin
  -- Validate the date window against the STUDIO's today, not the browser's.
  if p_booking_date is null then
    raise exception using errcode = 'PT400', message = 'Please choose a date.';
  end if;
  days_ahead := p_booking_date - public.studio_today();
  if days_ahead < 7 or days_ahead > 90 then
    raise exception using errcode = 'PT400',
      message = 'Please choose a date between 7 and 90 days from today.';
  end if;

  if p_wall_size_sqft is null or p_wall_size_sqft < 10 or p_wall_size_sqft > 500 then
    raise exception using errcode = 'PT400', message = 'Wall size must be between 10 and 500 sq ft.';
  end if;
  wall_size := round(p_wall_size_sqft, 2);

  if p_address is null or length(btrim(p_address)) < 5 or length(p_address) > 500 then
    raise exception using errcode = 'PT400', message = 'Please enter the full wall address.';
  end if;

  -- Price = seeded rate x size, calculated here. The browser's live
  -- calculator is only a preview.
  select s.mural_rate_per_sqft into rate from public.studio_settings s where s.id;
  if rate is null then
    raise exception 'Studio settings are missing. Run supabase/seed.sql first.';
  end if;

  -- The unique index bookings_one_active_per_date is what really prevents
  -- double booking: if two customers submit the same date at once, the
  -- second INSERT fails and we turn that into a friendly 409.
  begin
    insert into public.wall_bookings
      (customer_id, booking_date, wall_size_sqft, address, rate_per_sqft, total_price)
    values
      (caller_id, p_booking_date, wall_size, btrim(p_address), rate, round(rate * wall_size, 2))
    returning * into new_booking;
  exception when unique_violation then
    raise exception using errcode = 'PT409',
      message = 'That date is already booked. Please choose another date.';
  end;

  return new_booking;
end;
$$;

-- Customer cancels their own booking, up to 3 days before the date.
create or replace function public.cancel_wall_booking(p_booking_id uuid)
returns public.wall_bookings
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  booking     public.wall_bookings;
begin
  select * into booking
    from public.wall_bookings b
   where b.id = p_booking_id and b.customer_id = caller_id
   for update;

  if not found then
    raise exception using errcode = 'PT404', message = 'Booking not found.';
  end if;

  if booking.status not in ('requested', 'confirmed') then
    raise exception using errcode = 'PT409',
      message = format('This booking is already %s.', booking.status);
  end if;

  -- Last day to cancel = booking date minus 3 days.
  if public.studio_today() > booking.booking_date - 3 then
    raise exception using errcode = 'PT409',
      message = format('Bookings can only be cancelled until 3 days before the date (last day was %s).',
                       to_char(booking.booking_date - 3, 'DD Mon YYYY'));
  end if;

  update public.wall_bookings
     set status = 'cancelled', updated_at = now()
   where id = booking.id
  returning * into booking;

  return booking;
end;
$$;

-- Studio admin confirms or declines a 'requested' booking.
create or replace function public.studio_set_booking_status(p_booking_id uuid, p_new_status text)
returns public.wall_bookings
language plpgsql
security definer
set search_path = ''
as $$
declare
  booking public.wall_bookings;
begin
  perform public.require_studio();

  if p_new_status is null or p_new_status not in ('confirmed', 'declined') then
    raise exception using errcode = 'PT400', message = 'Status must be confirmed or declined.';
  end if;

  select * into booking from public.wall_bookings where id = p_booking_id for update;
  if not found then
    raise exception using errcode = 'PT404', message = 'Booking not found.';
  end if;

  if booking.status <> 'requested' then
    raise exception using errcode = 'PT409',
      message = format('Only requested bookings can be changed (this one is %s).', booking.status);
  end if;

  if p_new_status = 'confirmed' and booking.booking_date < public.studio_today() then
    raise exception using errcode = 'PT409', message = 'This booking date has already passed.';
  end if;

  update public.wall_bookings
     set status = p_new_status, updated_at = now()
   where id = booking.id
  returning * into booking;

  return booking;
end;
$$;


-- =====================================================================
-- POTTERY REQUESTS
-- =====================================================================

-- Shared validation for create and edit.
create or replace function public.validate_pottery_input(
  p_item_id text, p_glaze_id text, p_quantity integer, p_needed_by date, p_notes text)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_item_id is null or not exists (select 1 from public.pottery_items where id = p_item_id) then
    raise exception using errcode = 'PT400', message = 'Please choose a pottery item from the list.';
  end if;
  if p_glaze_id is null or not exists (select 1 from public.glazes where id = p_glaze_id) then
    raise exception using errcode = 'PT400', message = 'Please choose a glaze from the list.';
  end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 12 then
    raise exception using errcode = 'PT400', message = 'Quantity must be between 1 and 12.';
  end if;
  if p_needed_by is null or p_needed_by < public.studio_today() + 14 then
    raise exception using errcode = 'PT400',
      message = 'The needed-by date must be at least 14 days from today.';
  end if;
  if length(coalesce(p_notes, '')) > 500 then
    raise exception using errcode = 'PT400', message = 'Notes must be at most 500 characters.';
  end if;
end;
$$;

create or replace function public.create_pottery_request(
  p_item_id text, p_glaze_id text, p_quantity integer, p_needed_by date, p_notes text)
returns public.pottery_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  new_request public.pottery_requests;
begin
  perform public.validate_pottery_input(p_item_id, p_glaze_id, p_quantity, p_needed_by, p_notes);

  insert into public.pottery_requests (customer_id, item_id, glaze_id, quantity, needed_by, notes)
  values (caller_id, p_item_id, p_glaze_id, p_quantity, p_needed_by, btrim(coalesce(p_notes, '')))
  returning * into new_request;

  return new_request;
end;
$$;

-- Customer edits their own request — only while it is still 'requested'.
create or replace function public.update_pottery_request(
  p_request_id uuid, p_item_id text, p_glaze_id text, p_quantity integer,
  p_needed_by date, p_notes text)
returns public.pottery_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  request     public.pottery_requests;
begin
  select * into request
    from public.pottery_requests r
   where r.id = p_request_id and r.customer_id = caller_id
   for update;

  if not found then
    raise exception using errcode = 'PT404', message = 'Pottery request not found.';
  end if;
  if request.status <> 'requested' then
    raise exception using errcode = 'PT409',
      message = format('This request is already %s and can no longer be edited.', request.status);
  end if;

  perform public.validate_pottery_input(p_item_id, p_glaze_id, p_quantity, p_needed_by, p_notes);

  update public.pottery_requests
     set item_id = p_item_id, glaze_id = p_glaze_id, quantity = p_quantity,
         needed_by = p_needed_by, notes = btrim(coalesce(p_notes, '')), updated_at = now()
   where id = request.id
  returning * into request;

  return request;
end;
$$;

-- Customer cancels their own request — only while it is still 'requested'.
create or replace function public.cancel_pottery_request(p_request_id uuid)
returns public.pottery_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller_id   uuid := public.require_customer();
  request     public.pottery_requests;
begin
  select * into request
    from public.pottery_requests r
   where r.id = p_request_id and r.customer_id = caller_id
   for update;

  if not found then
    raise exception using errcode = 'PT404', message = 'Pottery request not found.';
  end if;
  if request.status <> 'requested' then
    raise exception using errcode = 'PT409',
      message = format('This request is already %s and can no longer be cancelled.', request.status);
  end if;

  update public.pottery_requests
     set status = 'cancelled', updated_at = now()
   where id = request.id
  returning * into request;

  return request;
end;
$$;

-- Studio admin accepts or declines a 'requested' pottery request.
create or replace function public.studio_set_pottery_status(p_request_id uuid, p_new_status text)
returns public.pottery_requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  request public.pottery_requests;
begin
  perform public.require_studio();

  if p_new_status is null or p_new_status not in ('accepted', 'declined') then
    raise exception using errcode = 'PT400', message = 'Status must be accepted or declined.';
  end if;

  select * into request from public.pottery_requests where id = p_request_id for update;
  if not found then
    raise exception using errcode = 'PT404', message = 'Pottery request not found.';
  end if;
  if request.status <> 'requested' then
    raise exception using errcode = 'PT409',
      message = format('Only requested items can be changed (this one is %s).', request.status);
  end if;

  update public.pottery_requests
     set status = p_new_status, updated_at = now()
   where id = request.id
  returning * into request;

  return request;
end;
$$;


-- =====================================================================
-- SINGLE-RECORD READS with explicit HTTP codes
-- (401 if logged out, 404 if the record doesn't exist OR isn't yours —
-- we never reveal that someone else's record exists.)
-- =====================================================================

create or replace function public.get_order(p_order_id uuid)
returns public.orders
language plpgsql stable security definer set search_path = ''
as $$
declare
  user_id uuid := public.require_login();
  result  public.orders;
begin
  select * into result from public.orders o
   where o.id = p_order_id and (o.customer_id = user_id or public.is_studio());
  if not found then
    raise exception using errcode = 'PT404', message = 'Order not found.';
  end if;
  return result;
end;
$$;

create or replace function public.get_wall_booking(p_booking_id uuid)
returns public.wall_bookings
language plpgsql stable security definer set search_path = ''
as $$
declare
  user_id uuid := public.require_login();
  result  public.wall_bookings;
begin
  select * into result from public.wall_bookings b
   where b.id = p_booking_id and (b.customer_id = user_id or public.is_studio());
  if not found then
    raise exception using errcode = 'PT404', message = 'Booking not found.';
  end if;
  return result;
end;
$$;

create or replace function public.get_pottery_request(p_request_id uuid)
returns public.pottery_requests
language plpgsql stable security definer set search_path = ''
as $$
declare
  user_id uuid := public.require_login();
  result  public.pottery_requests;
begin
  select * into result from public.pottery_requests r
   where r.id = p_request_id and (r.customer_id = user_id or public.is_studio());
  if not found then
    raise exception using errcode = 'PT404', message = 'Pottery request not found.';
  end if;
  return result;
end;
$$;

-- Dates already taken (for the booking form). Returns only dates, never
-- who booked them, so it is safe for any logged-in customer to call.
create or replace function public.booked_wall_dates()
returns setof date
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform public.require_login();
  return query
    select b.booking_date from public.wall_bookings b
     where b.status in ('requested', 'confirmed')
       and b.booking_date >= public.studio_today()
     order by 1;
end;
$$;

-- ##################### supabase/migrations/004_rls_and_grants.sql #####################
-- =====================================================================
-- 004_rls_and_grants.sql — Row Level Security and permissions
--
-- Two layers protect the data:
--   1. GRANTS decide WHAT a role may do at all. Browsers (roles 'anon'
--      and 'authenticated') get SELECT only. No INSERT/UPDATE/DELETE —
--      all changes must go through the checked functions in 003.
--   2. RLS POLICIES decide WHICH ROWS a role may see: customers see only
--      their own orders/bookings/requests, the studio sees everything.
-- =====================================================================

-- ---------- Turn on RLS for every table ----------
alter table public.studio_settings  enable row level security;
alter table public.profiles         enable row level security;
alter table public.paintings        enable row level security;
alter table public.orders           enable row level security;
alter table public.wall_bookings    enable row level security;
alter table public.pottery_items    enable row level security;
alter table public.glazes           enable row level security;
alter table public.pottery_requests enable row level security;

-- ---------- Table grants: read-only for the browser ----------
revoke all on all tables in schema public from anon, authenticated;

-- Public catalogue data: anyone (even logged out) may read it.
grant select on public.paintings, public.pottery_items, public.glazes, public.studio_settings
  to anon, authenticated;

-- Private data: logged-in users only (rows filtered by the policies below).
grant select on public.profiles, public.orders, public.wall_bookings, public.pottery_requests
  to authenticated;

-- Server-side scripts using the secret service_role key (never shipped to
-- the browser) may manage everything, e.g. scripts/provision-studio.js.
grant all on all tables in schema public to service_role;

-- ---------- Policies (drop first so this file can be re-run) ----------
drop policy if exists "Anyone can read studio settings" on public.studio_settings;
create policy "Anyone can read studio settings" on public.studio_settings
  for select using (true);

drop policy if exists "Anyone can read paintings" on public.paintings;
create policy "Anyone can read paintings" on public.paintings
  for select using (true);

drop policy if exists "Anyone can read pottery items" on public.pottery_items;
create policy "Anyone can read pottery items" on public.pottery_items
  for select using (true);

drop policy if exists "Anyone can read glazes" on public.glazes;
create policy "Anyone can read glazes" on public.glazes
  for select using (true);

drop policy if exists "Users read own profile, studio reads all" on public.profiles;
create policy "Users read own profile, studio reads all" on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_studio());

drop policy if exists "Customers read own orders, studio reads all" on public.orders;
create policy "Customers read own orders, studio reads all" on public.orders
  for select to authenticated
  using (customer_id = auth.uid() or public.is_studio());

drop policy if exists "Customers read own bookings, studio reads all" on public.wall_bookings;
create policy "Customers read own bookings, studio reads all" on public.wall_bookings
  for select to authenticated
  using (customer_id = auth.uid() or public.is_studio());

drop policy if exists "Customers read own pottery requests, studio reads all" on public.pottery_requests;
create policy "Customers read own pottery requests, studio reads all" on public.pottery_requests
  for select to authenticated
  using (customer_id = auth.uid() or public.is_studio());

-- ---------- Function grants ----------
-- Start from "nobody can call anything", then allow only the API.
revoke execute on all functions in schema public from public, anon, authenticated;

-- Needed inside RLS policies (policies run as the caller).
grant execute on function public.is_studio()          to anon, authenticated;
grant execute on function public.current_user_role()  to anon, authenticated;
grant execute on function public.studio_today()       to anon, authenticated;

-- The website's API. anon is allowed to CALL them so that a logged-out
-- request reaches require_login() and gets a clear HTTP 401 message.
grant execute on function
  public.purchase_painting(text),
  public.cancel_order(uuid),
  public.studio_add_painting(text, text, text, numeric, text),
  public.studio_update_painting(text, text, text, text, numeric, text),
  public.create_wall_booking(date, numeric, text),
  public.cancel_wall_booking(uuid),
  public.studio_set_booking_status(uuid, text),
  public.create_pottery_request(text, text, integer, date, text),
  public.update_pottery_request(uuid, text, text, integer, date, text),
  public.cancel_pottery_request(uuid),
  public.studio_set_pottery_status(uuid, text),
  public.get_order(uuid),
  public.get_wall_booking(uuid),
  public.get_pottery_request(uuid),
  public.booked_wall_dates()
to anon, authenticated;

grant execute on all functions in schema public to service_role;

